function projectile(v, angleDeg, h0, g){
  g = (g==null)?9.81:g; h0=(h0==null)?0:h0;
  var th = angleDeg*Math.PI/180;
  var vx = v*Math.cos(th), vy = v*Math.sin(th);
  var disc = vy*vy + 2*g*h0;
  var tFlight = (vy + Math.sqrt(disc))/g;
  var range = vx*tFlight;
  var maxH = h0 + vy*vy/(2*g);
  return {vx:vx, vy:vy, tFlight:tFlight, range:range, maxH:maxH, g:g};
}
function trajectory(v, angleDeg, h0, g, steps){
  steps=(steps==null)?40:steps; var p=projectile(v,angleDeg,h0,g); var pts=[];
  for(var i=0;i<=steps;i++){ var t=p.tFlight*i/steps; var x=p.vx*t; var y=h0+p.vy*t-0.5*g*t*t; pts.push([+x.toFixed(3), +Math.max(0,y).toFixed(3)]); }
  return pts;
}
var EXPORTS={ projectile:projectile, trajectory:trajectory, G:9.81 };

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.ProjectileForgePure = EXPORTS; }
